<?php
namespace App\Filament\Resources\Warranties;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Warranties\Pages\ManageWarranties; use App\Models\Warranty;
use BackedEnum; use Filament\Actions\BulkActionGroup; use Filament\Actions\DeleteAction; use Filament\Actions\DeleteBulkAction; use Filament\Actions\EditAction; use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\TextInput; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class WarrantyResource extends AdminResource {protected static ?string $model=Warranty::class;protected static string $viewPermission='warranties.manage';protected static ?string $managePermission='warranties.manage';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedShieldCheck;protected static ?string $navigationLabel='Phiếu bảo hành';protected static string|\UnitEnum|null $navigationGroup='Khách hàng & Hậu mãi';protected static ?int $navigationSort=40;private const STATUSES=['active'=>'Hiệu lực','expired'=>'Hết hạn','void'=>'Vô hiệu'];public static function form(Schema $s):Schema{return $s->components([Select::make('order_item_id')->relationship('orderItem','sku')->searchable()->preload(),TextInput::make('warranty_number')->label('Mã bảo hành')->required()->unique(ignoreRecord:true),DatePicker::make('starts_at')->label('Ngày bắt đầu')->required(),DatePicker::make('ends_at')->label('Ngày hết hạn')->required()->after('starts_at'),Select::make('status')->label('Trạng thái')->options(self::STATUSES)->default('active')->required(),Textarea::make('terms')->label('Điều khoản')->columnSpanFull()])->columns(2);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('warranty_number')->label('Mã')->searchable()->copyable()->weight('bold'),TextColumn::make('order_item_id')->label('ID dòng đơn'),TextColumn::make('starts_at')->label('Bắt đầu')->date(),TextColumn::make('ends_at')->label('Hết hạn')->date(),TextColumn::make('status')->label('Trạng thái')->badge()->formatStateUsing(fn($s)=>self::STATUSES[$s])])->filters([SelectFilter::make('status')->options(self::STATUSES)])->recordActions([EditAction::make()->label('Sửa'),DeleteAction::make()->label('Xóa')])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]);}public static function getPages():array{return ['index'=>ManageWarranties::route('/')];}}
